test('denied browser storage leaves all game controls playable', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', { get() { throw new DOMException('Storage blocked', 'SecurityError'); } });
  });
  await page.goto('/');
  await loadBoard(page);
  await finish(page);
  await expect(page.locator('.scoreboard')).toContainText('Best: 8');
  await page.getByRole('button', { name: 'New Game', exact: true }).click();
  await expect(cards(page)).toHaveCount(16);
});

test('a real hidden page pauses elapsed time and the pending mismatch', async ({ page, context }) => {
  await page.goto('/');
  await loadBoard(page);
  await page.clock.install();
  await page.clock.pauseAt(new Date());
  await cards(page).nth(0).click(); await cards(page).nth(1).click();
  await page.clock.runFor(200);
  // Chromium's Page lifecycle freeze supplies genuine visibility events.
  const cdp = await context.newCDPSession(page);
  await cdp.send('Page.setWebLifecycleState', { state: 'frozen' });
  const hidden = await page.evaluate(() => document.hidden);
  expect(hidden).toBe(true);
  await page.clock.runFor(2000);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await cdp.send('Page.setWebLifecycleState', { state: 'active' });
  await page.bringToFront();
  await page.clock.runFor(599);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(33);
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  await expect(page.locator('.scoreboard')).toContainText('Time: 0:00');
});

